export function awakenParams(r){
 const t=r.talents.bb,sk=k=>r.skills.find(s=>s.prefabKey===k),aoe=sk("AoeM2"),blink=sk("Blink"),lr=sk("AttackLR");
 return {
  journey:{speed:3,lifetime:6,radius:.5,scale:1,cooldown:lr.cooldown,initial:lr.initCooldown,anim:{duration:CLOCK.durations.Skill_1,release:CLOCK.events.Skill_1}},
  vision:{scale:sk("Aoe").bb.atk_scale,prepare:aoe.bb.aoe_prepare_duration,release:CLOCK.events.Skill_2_End,end:CLOCK.durations.Skill_2_End,stun:aoe.bb.stun},
  blink:{cooldown:blink.bb.cooldown_0,initial:blink.initCooldown,hide:1},
  rebirth:t["Reborn.duration"],rebornHp:1,form2Atk:t["M2.atk"],
 };
}
